from pathlib import Path
import base64,re
p=Path("tarjs/app/src/main/assets/web/app.js")
s=p.read_text()
snippet=base64.b64decode("").decode()
s,n=re.subn(r"function openChat\(.*?(?=function searchView\()",lambda _m: snippet,s,flags=re.S)
if n!=1: raise SystemExit(f"chat block replacement count={n}")
s=s.replace("function jump(chatId,msgId,name){S.chat={id:chatId,name};", "function jump(chatId,msgId,name){S.chat=j(TARJS.listChats(S.archive.id)).find(x=>x.id===chatId)||{id:chatId,name};")
p.write_text(s)
